output_text:
[
  {
    "id": "return_cart_to_service_bay",
    "text": "A shopper who uses a cart is obliged to return it to the service-desk return bay before leaving the store.",
    "abstraction": {
      "state_properties": {
        "service_return_bay": "at(0,1)",
        "cart_returned_at_service_bay": {
          "and": [
            "service_return_bay",
            "cartAt(0,1)"
          ]
        }
      },
      "events": {
        "deposit_cart_at_service_bay": {
          "pre": {
            "and": [
              "service_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned_at_service_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "deposit_cart_at_service_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Shoppers are prohibited from exiting the store while still holding or pushing a shopping cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_possession": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "cart_in_possession"
        ]
      }
    }
  },
  {
    "id": "must_take_entrance_cart",
    "text": "At the start of a shopping trip, the shopper is obliged to take a cart from the entrance cart station.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": "at(1,5)",
        "cart_waiting_at_entrance": {
          "and": [
            "entrance_cart_station",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_cart_from_entrance": {
          "pre": {
            "and": [
              "cart_waiting_at_entrance",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_cart_from_entrance"
    }
  },
  {
    "id": "no_hand_carried_items",
    "text": "Merchandise must not be hand-carried; item pickups should occur only while the shopper has a cart.",
    "abstraction": {
      "state_properties": {
        "item_in_hand": "handFull",
        "has_container": "hasCart"
      },
      "events": {
        "pickup_item_by_hand": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "has_container"
              }
            ]
          },
          "post": "item_in_hand"
        },
        "pickup_item_into_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "has_container"
            ]
          },
          "post": "has_container"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "item_in_hand",
          "pickup_item_by_hand"
        ]
      }
    }
  },
  {
    "id": "retrieve_temporarily_parked_cart",
    "text": "If a shopper temporarily parks a cart away from the official return bay, they are obliged to pick it back up before continuing.",
    "abstraction": {
      "state_properties": {
        "dairy_cart_bay": "at(5,4)",
        "cart_temporarily_parked_at_dairy": {
          "and": [
            "dairy_cart_bay",
            "cartAt(5,4)"
          ]
        }
      },
      "events": {
        "park_cart_at_dairy_bay": {
          "pre": {
            "and": [
              "dairy_cart_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_temporarily_parked_at_dairy"
        },
        "retrieve_cart_from_dairy_bay": {
          "pre": {
            "and": [
              "cart_temporarily_parked_at_dairy",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "park_cart_at_dairy_bay",
      "discharge": "retrieve_cart_from_dairy_bay"
    }
  },
  {
    "id": "do_not_walk_away_from_parked_cart",
    "text": "A shopper is prohibited from moving away while their cart is temporarily parked in the shopping aisle.",
    "abstraction": {
      "state_properties": {
        "temporary_aisle_cart": "cartAt(5,4)"
      },
      "events": {
        "cart_left_in_aisle": {
          "pre": {
            "and": [
              "at(5,4)",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "temporary_aisle_cart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "temporary_aisle_cart",
          "MOVE"
        ]
      }
    }
  },
  {
    "id": "return_from_cart_passing_bay",
    "text": "When a shopper with a cart steps south from the dairy bay into the passing bay, they are obliged to return north to the dairy bay.",
    "abstraction": {
      "state_properties": {
        "dairy_bay": "at(5,4)",
        "south_passing_bay": "at(5,5)",
        "with_cart": "hasCart"
      },
      "events": {
        "cart_enters_south_passing_bay": {
          "pre": {
            "and": [
              "dairy_bay",
              "with_cart",
              "S"
            ]
          },
          "post": {
            "and": [
              "south_passing_bay",
              "with_cart"
            ]
          }
        },
        "cart_returns_north_to_dairy_bay": {
          "pre": {
            "and": [
              "south_passing_bay",
              "with_cart",
              "N"
            ]
          },
          "post": {
            "and": [
              "dairy_bay",
              "with_cart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_enters_south_passing_bay",
      "discharge": "cart_returns_north_to_dairy_bay"
    }
  },
  {
    "id": "clear_side_waiting_bay_with_cart",
    "text": "When a shopper with a cart moves into the lower-left waiting bay, they are obliged to clear it by moving back east.",
    "abstraction": {
      "state_properties": {
        "lower_left_waiting_bay": "at(4,5)",
        "lower_right_aisle_bay": "at(5,5)",
        "with_cart": "hasCart"
      },
      "events": {
        "cart_enters_left_waiting_bay": {
          "pre": {
            "and": [
              "lower_right_aisle_bay",
              "with_cart",
              "W"
            ]
          },
          "post": {
            "and": [
              "lower_left_waiting_bay",
              "with_cart"
            ]
          }
        },
        "cart_clears_left_waiting_bay": {
          "pre": {
            "and": [
              "lower_left_waiting_bay",
              "with_cart",
              "E"
            ]
          },
          "post": {
            "and": [
              "lower_right_aisle_bay",
              "with_cart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_enters_left_waiting_bay",
      "discharge": "cart_clears_left_waiting_bay"
    }
  }
]
